#if UNITY_EDITOR
using UnityEngine;
using UnityEditor;
using System.IO;

namespace WattsTap.Scripts.Game.GlobalConfigs.Editor
{
    /// <summary>
    /// Кастомный инспектор для PlayerLevelConfig с функцией импорта из CSV
    /// </summary>
    [CustomEditor(typeof(PlayerLevelConfig))]
    public class PlayerLevelConfigEditor : UnityEditor.Editor
    {
        private string csvPath = "Assets/CvsConfigs/WattsBalanceLevelupProfile.csv";

        public override void OnInspectorGUI()
        {
            DrawDefaultInspector();

            PlayerLevelConfig config = (PlayerLevelConfig)target;

            EditorGUILayout.Space(20);
            EditorGUILayout.LabelField("CSV Import Tools", EditorStyles.boldLabel);
            EditorGUILayout.HelpBox(
                "Импорт данных из WattsBalanceLevelupProfile.csv. " +
                "Это перезапишет все текущие значения в конфигурации.", 
                MessageType.Info);

            EditorGUILayout.BeginHorizontal();
            EditorGUILayout.LabelField("CSV File Path:", GUILayout.Width(100));
            csvPath = EditorGUILayout.TextField(csvPath);
            EditorGUILayout.EndHorizontal();

            if (GUILayout.Button("Import from CSV", GUILayout.Height(30)))
            {
                ImportFromCSV(config);
            }

            EditorGUILayout.Space(10);

            if (GUILayout.Button("Validate Configuration", GUILayout.Height(25)))
            {
                ValidateConfig(config);
            }

            EditorGUILayout.Space(10);
            EditorGUILayout.LabelField("Statistics", EditorStyles.boldLabel);

            if (config.levels != null && config.levels.Length > 0)
            {
                EditorGUILayout.LabelField($"Levels configured: {config.levels.Length}");

                // Показываем статистику последнего уровня
                var lastLevel = config.levels[config.levels.Length - 1];
                EditorGUILayout.LabelField($"Max level: {lastLevel.level}");
                EditorGUILayout.LabelField($"Total exp required: {lastLevel.sumExp:N0}");

                // Подсчитываем общие награды
                long totalCoins = 0;
                int totalDraws = 0;
                int totalChests = 0;

                foreach (var level in config.levels)
                {
                    if (level != null && level.rewards != null)
                    {
                        totalCoins += level.rewards.coins;
                        totalDraws += level.rewards.draws;
                        totalChests += level.rewards.GetTotalChests();
                    }
                }

                EditorGUILayout.Space(5);
                EditorGUILayout.LabelField("Total Rewards:", EditorStyles.boldLabel);
                EditorGUILayout.LabelField($"Coins: {totalCoins:N0}");
                EditorGUILayout.LabelField($"Draws: {totalDraws}");
                EditorGUILayout.LabelField($"Chests: {totalChests}");
            }
        }

        private void ImportFromCSV(PlayerLevelConfig config)
        {
            if (!File.Exists(csvPath))
            {
                EditorUtility.DisplayDialog(
                    "Error", 
                    $"CSV file not found at path:\n{csvPath}\n\nPlease check the path and try again.", 
                    "OK");
                return;
            }

            if (EditorUtility.DisplayDialog(
                "Import CSV", 
                "This will overwrite all current configuration values.\n\nAre you sure you want to continue?", 
                "Yes, Import", 
                "Cancel"))
            {
                try
                {
                    Undo.RecordObject(config, "Import CSV Data");

                    string csvText = File.ReadAllText(csvPath);
                    PlayerLevelCsvConverter.ParseCsvToConfig(csvText, config);

                    EditorUtility.SetDirty(config);
                    AssetDatabase.SaveAssets();

                    EditorUtility.DisplayDialog(
                        "Success", 
                        $"CSV data imported successfully!\n\n{config.levels.Length} levels loaded.\n\nCheck the console for any warnings.", 
                        "OK");
                }
                catch (System.Exception e)
                {
                    EditorUtility.DisplayDialog(
                        "Error", 
                        $"Failed to import CSV:\n\n{e.Message}", 
                        "OK");
                    Debug.LogError($"[PlayerLevelConfigEditor] Import failed: {e}");
                }
            }
        }

        private void ValidateConfig(PlayerLevelConfig config)
        {
            bool hasErrors = false;
            int errorCount = 0;
            int warningCount = 0;

            // Проверка наличия уровней
            if (config.levels == null || config.levels.Length == 0)
            {
                Debug.LogError("[PlayerLevelConfig] No levels configured");
                hasErrors = true;
                errorCount++;
            }
            else
            {
                // Проверка последовательности уровней
                for (int i = 0; i < config.levels.Length; i++)
                {
                    var level = config.levels[i];

                    if (level == null)
                    {
                        Debug.LogError($"[PlayerLevelConfig] Level at index {i} is null");
                        hasErrors = true;
                        errorCount++;
                        continue;
                    }

                    if (level.level != i + 1)
                    {
                        Debug.LogWarning($"[PlayerLevelConfig] Level mismatch at index {i}: expected {i + 1}, got {level.level}");
                        warningCount++;
                    }

                    // Проверка прогрессии опыта
                    if (i > 0)
                    {
                        var prevLevel = config.levels[i - 1];
                        if (level.sumExp <= prevLevel.sumExp)
                        {
                            Debug.LogError($"[PlayerLevelConfig] Level {level.level}: Sum exp ({level.sumExp}) must be greater than previous level ({prevLevel.sumExp})");
                            hasErrors = true;
                            errorCount++;
                        }
                    }

                    // Проверка наград
                    if (level.rewards == null)
                    {
                        Debug.LogWarning($"[PlayerLevelConfig] Level {level.level}: No rewards configured");
                        warningCount++;
                    }
                }

                // Проверка что первый уровень имеет sumExp = 0
                if (config.levels[0].sumExp != 0)
                {
                    Debug.LogWarning($"[PlayerLevelConfig] Level 1 should have sumExp = 0, got {config.levels[0].sumExp}");
                    warningCount++;
                }
            }

            if (!hasErrors && warningCount == 0)
            {
                EditorUtility.DisplayDialog(
                    "Validation Success", 
                    "Configuration is valid! No errors or warnings found.", 
                    "OK");
            }
            else
            {
                EditorUtility.DisplayDialog(
                    "Validation Complete", 
                    $"Validation completed with:\n\nErrors: {errorCount}\nWarnings: {warningCount}\n\nCheck the console for details.", 
                    "OK");
            }
        }
    }
}
#endif

using System;
using System.Collections.Generic;
using System.Globalization;
using UnityEngine;

namespace WattsTap.Scripts.Game.GlobalConfigs
{
    /// <summary>
    /// Утилита для конвертации данных из WattsBalanceLevelupProfile.csv в PlayerLevelConfig
    /// </summary>
    public static class PlayerLevelCsvConverter
    {
        private const char CsvSeparator = ',';

        /// <summary>
        /// Парсит CSV файл и заполняет конфигурацию
        /// </summary>
        /// <param name="csvText">Текст CSV файла</param>
        /// <param name="config">Конфигурация для заполнения</param>
        public static void ParseCsvToConfig(string csvText, PlayerLevelConfig config)
        {
            if (string.IsNullOrEmpty(csvText))
            {
                Debug.LogError("[PlayerLevelCsvConverter] CSV text is null or empty");
                return;
            }

            if (config == null)
            {
                Debug.LogError("[PlayerLevelCsvConverter] Config is null");
                return;
            }

            try
            {
                var lines = csvText.Split(new[] { '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries);

                // Парсим данные уровней
                ParseLevelData(lines, config);

                Debug.Log("[PlayerLevelCsvConverter] Successfully parsed CSV data");
            }
            catch (Exception e)
            {
                Debug.LogError($"[PlayerLevelCsvConverter] Error parsing CSV: {e.Message}\n{e.StackTrace}");
            }
        }

        /// <summary>
        /// Парсит данные уровней из CSV
        /// </summary>
        private static void ParseLevelData(string[] lines, PlayerLevelConfig config)
        {
            // Находим заголовок таблицы
            int headerIndex = -1;
            for (int i = 0; i < lines.Length; i++)
            {
                if (lines[i].Contains("LEVEL #") && lines[i].Contains("NEED EXP"))
                {
                    headerIndex = i;
                    break;
                }
            }

            if (headerIndex == -1)
            {
                Debug.LogWarning("[PlayerLevelCsvConverter] Level data header not found");
                return;
            }

            // Парсим заголовок для определения колонок
            var headerParts = SplitCsvLine(lines[headerIndex]);
            var columnMap = new Dictionary<string, int>();

            for (int i = 0; i < headerParts.Length; i++)
            {
                var columnName = headerParts[i].Trim();
                if (!string.IsNullOrEmpty(columnName))
                {
                    columnMap[columnName] = i;
                }
            }

            // Подсчитываем количество уровней
            var levelDataLines = new List<string[]>();
            for (int i = headerIndex + 2; i < lines.Length; i++) // +2 чтобы пропустить строку с суммами наград
            {
                var parts = SplitCsvLine(lines[i]);
                if (parts.Length > 0 && !string.IsNullOrWhiteSpace(parts[0]))
                {
                    // Проверяем что это строка с уровнем
                    if (int.TryParse(parts[0].Trim(), out int level) && level > 0)
                    {
                        levelDataLines.Add(parts);
                    }
                }
            }

            // Инициализируем массив уровней
            int maxLevel = levelDataLines.Count;
            config.levels = new PlayerLevelData[maxLevel];

            // Заполняем данные для каждого уровня
            for (int i = 0; i < levelDataLines.Count; i++)
            {
                var parts = levelDataLines[i];
                var levelData = new PlayerLevelData
                {
                    level = i + 1
                };

                // Level #
                if (columnMap.TryGetValue("LEVEL #", out int levelCol) && levelCol < parts.Length)
                {
                    levelData.level = ParseInt(parts[levelCol], i + 1);
                }

                // Cof Exp
                if (columnMap.TryGetValue("Cof Exp", out int cofExpCol) && cofExpCol < parts.Length)
                {
                    levelData.expCoefficient = ParseFloat(parts[cofExpCol], 1.0f);
                }

                // NEED EXP
                if (columnMap.TryGetValue("NEED EXP", out int needExpCol) && needExpCol < parts.Length)
                {
                    levelData.needExp = ParseLong(parts[needExpCol], 0);
                }

                // SUM EXP
                if (columnMap.TryGetValue("SUM EXP", out int sumExpCol) && sumExpCol < parts.Length)
                {
                    levelData.sumExp = ParseLong(parts[sumExpCol], 0);
                }

                // Rewards
                levelData.rewards = new LevelRewards();

                // COINS
                if (columnMap.TryGetValue("COINS", out int coinsCol) && coinsCol < parts.Length)
                {
                    levelData.rewards.coins = ParseLong(parts[coinsCol], 0);
                }

                // DRAW
                if (columnMap.TryGetValue("DRAW", out int drawCol) && drawCol < parts.Length)
                {
                    levelData.rewards.draws = ParseInt(parts[drawCol], 0);
                }

                // C CHEST (Common)
                if (columnMap.TryGetValue("C CHEST", out int cChestCol) && cChestCol < parts.Length)
                {
                    levelData.rewards.commonChests = ParseInt(parts[cChestCol], 0);
                }

                // U CHEST (Uncommon)
                if (columnMap.TryGetValue("U CHEST", out int uChestCol) && uChestCol < parts.Length)
                {
                    levelData.rewards.uncommonChests = ParseInt(parts[uChestCol], 0);
                }

                // R CHEST (Rare)
                if (columnMap.TryGetValue("R CHEST", out int rChestCol) && rChestCol < parts.Length)
                {
                    levelData.rewards.rareChests = ParseInt(parts[rChestCol], 0);
                }

                // L CHEST (Legendary)
                if (columnMap.TryGetValue("L CHEST", out int lChestCol) && lChestCol < parts.Length)
                {
                    levelData.rewards.legendaryChests = ParseInt(parts[lChestCol], 0);
                }

                config.levels[i] = levelData;
            }

            Debug.Log($"[PlayerLevelCsvConverter] Parsed {config.levels.Length} levels");
        }

        /// <summary>
        /// Разбивает CSV строку на части, учитывая кавычки
        /// </summary>
        private static string[] SplitCsvLine(string line)
        {
            var result = new List<string>();
            var currentField = "";
            bool inQuotes = false;

            for (int i = 0; i < line.Length; i++)
            {
                char c = line[i];

                if (c == '"')
                {
                    inQuotes = !inQuotes;
                }
                else if (c == CsvSeparator && !inQuotes)
                {
                    result.Add(currentField);
                    currentField = "";
                }
                else
                {
                    currentField += c;
                }
            }

            result.Add(currentField);
            return result.ToArray();
        }

        /// <summary>
        /// Парсит целое число с обработкой ошибок
        /// </summary>
        private static int ParseInt(string value, int defaultValue)
        {
            if (string.IsNullOrWhiteSpace(value))
                return defaultValue;

            value = value.Trim().Replace(" ", "");

            if (int.TryParse(value, NumberStyles.Any, CultureInfo.InvariantCulture, out int result))
                return result;

            return defaultValue;
        }

        /// <summary>
        /// Парсит длинное целое число с обработкой ошибок
        /// </summary>
        private static long ParseLong(string value, long defaultValue)
        {
            if (string.IsNullOrWhiteSpace(value))
                return defaultValue;

            value = value.Trim().Replace(" ", "");

            if (long.TryParse(value, NumberStyles.Any, CultureInfo.InvariantCulture, out long result))
                return result;

            return defaultValue;
        }

        /// <summary>
        /// Парсит дробное число с обработкой ошибок и различных форматов
        /// </summary>
        private static float ParseFloat(string value, float defaultValue)
        {
            if (string.IsNullOrWhiteSpace(value))
                return defaultValue;

            value = value.Trim().Replace(" ", "").Replace(",", ".");

            if (float.TryParse(value, NumberStyles.Any, CultureInfo.InvariantCulture, out float result))
                return result;

            return defaultValue;
        }
    }
}
